            ps.setInt(1, roomNumber);
            ps.setDate(2, Date.valueOf(out));
            ps.setDate(3, Date.valueOf(in));
            try (ResultSet r = ps.executeQuery()) {
                return r.next();
            }
        }
    }

    public static Reservation insert(Connection c, Reservation v) throws SQLException {
