        assertEquals(m("499.80"), q.subtotal());
        assertEquals(m("74.97"), q.discount());
        assertEquals(m("0.00"), RatePlans.require("NON_REFUNDABLE").refund(q.total()));
    }

    @Test void receiptText() {
